// creating arrays of pointers to the frames for each animation

const uint8_t*idle_animation[] = {frame0, frame1, frame2, frame3, frame4, frame5, frame6, frame7, frame8, frame9, frame10, frame11, frame12, frame13, frame14, frame15, frame16, frame17, frame18, frame19, frame20, frame21, frame22, frame23};
const uint8_t num_idle_frames = 24;

const uint8_t*surprised_animation[] = {frame0_2, frame1_2, frame2_2, frame3_2, frame4_2, frame5_2, frame6_2, frame7_2};
const uint8_t num_surprised_frames = 8;

const uint8_t*running_animation[] = {frame10_2, frame11_2, frame12_2, frame13_2, frame14_2, frame15_2, frame16_2};
const uint8_t num_running_frames = 7;

const uint8_t*sleeping_animation[] = {frame0_3, frame1_3, frame2_3, frame3_3, frame4_3, frame5_3, frame6_3, frame7_3, frame8_3, frame9_3};
const uint8_t num_sleeping_frames = 10;

const uint8_t*why_in_oufit[] = {frame0_4, frame1_4, frame2_4, frame3_4, frame4_4, frame5_4, frame6_4, frame7_4, frame8_4, frame9_4, frame10_4, frame11_4, frame12_4, frame13_4, frame14_4, frame15_4, frame16_4, frame17_4};
const uint8_t num_why_in_oufit_frames = 18;

const uint8_t*where_did_you_go[] = {frame0_5, frame1_5, frame2_5, frame3_5, frame4_5, frame5_5, frame6_5, frame7_5, frame8_5, frame9_5, frame10_5, frame11_5, frame12_5, frame13_5, frame14_5};
const uint8_t num_where_did_you_go_frames = 15;

const uint8_t*omg_you_almost_made_me_cry[] = {frame0_6, frame1_6, frame2_6, frame3_6, frame4_6, frame5_6, frame6_6, frame7_6, frame8_6, frame9_6, frame10_6, frame11_6, frame12_6, frame13_6, frame14_6, frame15_6, frame16_6, frame17_6, frame18_6, frame19_6, frame20_6, frame21_6, frame22_6, frame23_6, frame24_6, frame25_6, frame26_6, frame27_6, frame28_6, frame29_6, frame30_6, frame31_6, frame32_6, frame33_6};
const uint8_t num_omg_you_almost_made_me_cry_frames = 34;

const uint8_t*flabergasted_animation[] = {frame0_7, frame1_7, frame2_7, frame3_7, frame4_7, frame5_7, frame6_7, frame7_7, frame8_7, frame9_7};
const uint8_t num_flabergasted_frames = 10;


unsigned long lastAnimMs = 0;
int currentFrameIdx = 0;
const int ANIMATION_DELAY_MS = 67; 

enum State {
  IDLE,
  WHY_IN_OUTFIT,
  WHERE_DID_YOU_GO,
  SURPRISED,
  RUNNING,
  SLEEPING,
  FLABERGASTED,
  OMG_YOU_ALMOST_MADE_ME_CRY
};

State currentState = IDLE;
State previousState = IDLE; 

#define demo_mode 1
#if demo_mode
const float time_scale = 60.0;
#else
const float time_scale = 1.0;
#endif
  const unsigned long five_min = 5 * 60 * 1000UL / time_scale;
  const unsigned long ten_min = 10 * 60 * 1000UL / time_scale;
  const unsigned long two_hours = 2 * 60 * 60 * 1000UL / time_scale;
  const unsigned long six_hours = 6 * 60 * 60 * 1000UL / time_scale;

unsigned long stateEntrytime = 0;
unsigned long runningstarts = 0;
unsigned long distancesamplecount = 0;
unsigned long cumulativerunningMs = 0;
unsigned long lastrunningtickMs = 0;

float lastdistance = 0.0;
float distancesum = 0.0;
const float DISTANCE_THRESHOLD_INCHES = 15.0;

unsigned long lastDistanceCheckMs = 0;
const int DISTANCE_CHECK_INTERVAL_MS = 60;

unsigned long lastPrintMS = 0;
const unsigned long PRINT_INTERVAL_MS = 5000;

bool flabergastedtriggered = false;
bool playAnimation(const uint8_t** frames, uint8_t numFrames);

bool displayIdle() { return playAnimation(idle_animation, num_idle_frames);}
bool displayRunning() {return playAnimation(running_animation, num_running_frames);}
bool displaySURPRISED() {return playAnimation(surprised_animation, num_surprised_frames);}
bool displayWHERE_DID_YOU_GO() {return playAnimation(where_did_you_go, num_where_did_you_go_frames);}
bool displayWHY_IN_OUTFIT() {return playAnimation(why_in_oufit, num_why_in_oufit_frames);}
bool displayFlabergasted() {return playAnimation(flabergasted_animation, num_flabergasted_frames);}
bool displayOMG_YOU_ALMOST_MADE_ME_CRY() {return playAnimation(omg_you_almost_made_me_cry, num_omg_you_almost_made_me_cry_frames);}
bool displaySleeping() {return playAnimation(sleeping_animation, num_sleeping_frames);}

float getDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000); 

  if (duration == 0) {
    return 999.0;
  }

  int distanceInches = duration * 0.0133 / 2;
  return distanceInches;
}

void setup() {
  Serial.begin(115200);
  Wire.begin();

  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDR)) {
  Serial.println(F("SSD1306 allocation failed"));
  for (;;);
}
display.display();
delay(2000);
display.clearDisplay();

stateEntrytime = millis();
}

void loop() {

  unsigned long currentTime = millis();
  if (currentTime - lastDistanceCheckMs >= DISTANCE_CHECK_INTERVAL_MS) {
    lastdistance = getDistance();
    lastDistanceCheckMs = currentTime;
  }
  if (currentTime - lastPrintMS >= PRINT_INTERVAL_MS) {
    Serial.print("distance in inchs: ");
    Serial.println(lastdistance);
    lastPrintMS = currentTime;
  }

    distancesum += lastdistance;
    distancesamplecount++;

  if (currentState != previousState) {
    currentFrameIdx = 0;
    lastAnimMs = currentTime;
    previousState = currentState;
    stateEntrytime = currentTime;
    runningstarts = currentTime;
    distancesum = 0.0;
    distancesamplecount = 0;
  }
if (!flabergastedtriggered && currentTime >= six_hours) {
    currentState = FLABERGASTED;
    flabergastedtriggered = true;
  }

// THE LOVELY LOGIC T-T
  switch (currentState) {
    case IDLE:{
      displayIdle();
      if (currentTime - stateEntrytime >= five_min) {
        float avgDistance = distancesum / distancesamplecount;
        currentState = (avgDistance > DISTANCE_THRESHOLD_INCHES) ? WHERE_DID_YOU_GO : RUNNING;
        stateEntrytime = currentTime;
        distancesum = 0.0;
        distancesamplecount = 0;
      }
      break;
  }
    case RUNNING:{
      displayRunning();
        if (currentTime - runningstarts >= five_min) {
          float avgDistance = distancesum / distancesamplecount;
          if (avgDistance > DISTANCE_THRESHOLD_INCHES) currentState = WHERE_DID_YOU_GO;
          runningstarts = currentTime;
          distancesum = 0.0;
          distancesamplecount = 0;
        }
        if (currentTime - stateEntrytime >= two_hours) {
          currentState = SURPRISED;
        }
        break;
  }
    case WHERE_DID_YOU_GO:{
      displayWHERE_DID_YOU_GO();
      if (currentTime - stateEntrytime >= five_min) {
        float avgDistance = distancesum / distancesamplecount;
        currentState = (avgDistance > DISTANCE_THRESHOLD_INCHES) ? SLEEPING : RUNNING;
        stateEntrytime = currentTime;
        distancesum = 0.0;
        distancesamplecount = 0;
            }
      break;
  }
    case WHY_IN_OUTFIT:{
      displayWHY_IN_OUTFIT();
      if (currentTime - stateEntrytime >= five_min) {
        float avgDistance = distancesum / distancesamplecount;
        currentState = (avgDistance <= DISTANCE_THRESHOLD_INCHES) ? RUNNING : SLEEPING;
        stateEntrytime = currentTime;
        distancesum = 0.0;
        distancesamplecount = 0;
      }
      break;
  }
    case SLEEPING:{
      displaySleeping();
      unsigned long elapsed = currentTime - stateEntrytime;
      float avgDistance = (distancesamplecount > 0) ? distancesum / distancesamplecount : lastdistance; 
      if (lastdistance < DISTANCE_THRESHOLD_INCHES) {
        currentState = WHY_IN_OUTFIT;
      } else if (elapsed >= ten_min) {
        currentState = OMG_YOU_ALMOST_MADE_ME_CRY;
      }
      break;
    }
    //now for my favourite cases i consider them special because they are really helpful for me (somone who spends good amount of time on his desk)
    case SURPRISED:{
      displaySURPRISED();
      if (currentTime - stateEntrytime >= five_min) {
        float avgDistance = distancesum / distancesamplecount;
        currentState = (avgDistance > DISTANCE_THRESHOLD_INCHES) ? IDLE : RUNNING;
        stateEntrytime = currentTime;
        distancesum = 0.0;
        distancesamplecount = 0;
      }
      break;
    }
    case FLABERGASTED:{
      displayFlabergasted();
      if (currentTime - stateEntrytime >= ten_min) {
        currentState = IDLE;
      }
      break;
    }
    case OMG_YOU_ALMOST_MADE_ME_CRY:{
      bool finished = displayOMG_YOU_ALMOST_MADE_ME_CRY();
      if (finished) 
        currentState = IDLE;
        break;
      }
    }
  delay(10);
}
void drawelapsedtime(unsigned long elapsedMS, uint16_t color) {
  unsigned long seconds = elapsedMS / 1000;
  unsigned long minutes = (seconds % 3600) / 60;
  unsigned long hours = seconds / 3600;

  char buf[9];
  snprintf(buf, sizeof(buf), "%02u:%02u:%02u", hours, minutes, seconds);

  display.setTextSize(1);
  display.setTextColor(color);

  int16_t x1, y1;
  uint16_t w, h;
display.getTextBounds(buf, 0, 0, &x1, &y1, &w, &h);

  int16_t x = (display.width() - w) / 2;
  int16_t y = 0;

  display.setCursor(x, y);
  display.print(buf);
}
bool playAnimation(const uint8_t** frames, uint8_t numFrames) {
  bool finished = false;
  if (millis() - lastAnimMs >= ANIMATION_DELAY_MS) {
    lastAnimMs = millis();
    display.clearDisplay();
    display.drawBitmap(0, 0, frames[currentFrameIdx], 128, 64, SSD1306_WHITE);
    drawelapsedtime(millis() - stateEntrytime, SSD1306_WHITE);
    display.display();
    currentFrameIdx = (currentFrameIdx + 1) % numFrames;
    if (currentFrameIdx == 0) {
      finished = true;
    }
  }
  return finished;
}
